eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   siteContent: () => (/* binding */ siteContent)\n/* harmony export */ });\nconst siteContent = {\n    brand: {\n        name: \"Impackt Gifting Solutions\",\n        tagline: \"Gifts That Make an Impression.\",\n        description: \"Thoughtfully curated gifts for life's special moments, celebrations, and the people who matter.\",\n        founded: 2023,\n        founder: \"Rushabh Shah\",\n        legacy: \"60 years of excellence in kitchenware and gifting\",\n        vision: \"To be the go-to destination for premium gifting solutions in India.\",\n        mission: \"To bridge the gap between heartfelt emotions and meaningful expressions through meticulously curated gifts that leave a lasting impression.\",\n        values: [\n            {\n                title: \"Heritage\",\n                description: \"Built on six decades of trust, we bring the wisdom of our kitchenware legacy into every gift we curate.\"\n            },\n            {\n                title: \"Craftsmanship\",\n                description: \"We source from trusted suppliers and artisans, ensuring every item meets the highest standards of quality and durability.\"\n            },\n            {\n                title: \"Personal Touch\",\n                description: \"Every relationship is unique. We believe in gifts that speak directly to the recipient, making moments unforgettable.\"\n            },\n            {\n                title: \"Indian by Heart\",\n                description: \"From Diwali hampers to corporate client gifts, we understand the nuances of Indian gifting culture and relationships.\"\n            },\n            {\n                title: \"Sustainability\",\n                description: \"We are committed to eco-friendly practices, offering sustainable packaging and ethically sourced products.\"\n            }\n        ]\n    },\n    contact: {\n        address: \"19A, Ram Mohan Dutta Rd, Sreepally, Bhowanipore, Kolkata, West Bengal 700020\",\n        phone: \"+91 73372 88823\",\n        email: \"info@impacktgifting.com\"\n    },\n    hero: {\n        headline: \"Gifts That Make an Impression.\",\n        subheadline: \"Thoughtfully curated gifts for life's special moments, celebrations, and the people who matter.\",\n        primaryCta: \"Shop Gifts\",\n        secondaryCta: \"Corporate Gifting\",\n        image: \"https://picsum.photos/seed/hero-gifting/1920/1080\"\n    },\n    about: {\n        paragraphs: [\n            \"Welcome to Impackt Gifting Solutions (IGS), where we bring the art of gifting to a whole new level. Founded in 2023 by Rushabh Shah, IGS is built upon a legacy of excellence and innovation in the SS Kitchenware business, which has been thriving for the past 60 years.\",\n            \"Our journey began in the heart of Kolkata, where our family business became synonymous with quality kitchenware. Over six decades, we built trust with thousands of households and businesses across India. In 2023, we channeled that same trust and taste into gifting — creating Impackt Gifting Solutions.\",\n            \"We believe gifting is not just about products. It is about emotions, relationships, and the stories we tell through thoughtful gestures. Whether it is a birthday, a festival, a corporate milestone, or a simple thank you, we curate gifts that resonate.\",\n            \"Today, Impackt Gifting Solutions stands at the intersection of tradition and modernity. We combine our deep understanding of Indian gifting culture with contemporary design, premium quality, and personalized touches that make every gift extraordinary.\",\n            \"Our mission is simple: to make every occasion memorable with gifts that truly make an impression.\"\n        ],\n        history: [\n            {\n                year: \"1960s\",\n                title: \"The Beginning\",\n                description: \"Our family establishes SS Kitchenware in Kolkata, building a reputation for quality and trust.\"\n            },\n            {\n                year: \"1980s\",\n                title: \"Expansion\",\n                description: \"We expand our product range and distribution across West Bengal, becoming a household name.\"\n            },\n            {\n                year: \"2000s\",\n                title: \"National Reach\",\n                description: \"We extend our presence across India, serving both retail and corporate clients.\"\n            },\n            {\n                year: \"2023\",\n                title: \"Impackt Gifting Solutions\",\n                description: \"Launching a dedicated gifting brand to redefine how India gives and receives gifts.\"\n            }\n        ],\n        beliefs: [\n            \"Gifting is a language of love, respect, and gratitude.\",\n            \"Every gift should reflect the thought behind it, not just its price tag.\",\n            \"Indian gifting traditions deserve modern, premium expressions.\",\n            \"Sustainability and ethics are non-negotiable in the products we choose.\",\n            \"Corporate gifting is an art that builds lasting relationships.\"\n        ]\n    },\n    differentiators: [\n        {\n            title: \"Personalization Excellence\",\n            description: \"We understand that every individual is unique, and every relationship is special. That's why we offer a wide range of personalized gifts that can be tailored to suit your recipient's personality and preferences. From custom-made gift baskets to monogrammed keepsakes, we're here to help you create memorable moments.\"\n        },\n        {\n            title: \"Corporate Gifting Expertise\",\n            description: \"Impackt Gifting Solutions is your trusted partner in corporate gifting. We recognize the importance of nurturing business relationships, and our team of experts is dedicated to curating corporate gift solutions that reflect your brand's identity and convey your appreciation to clients, partners, and employees.\"\n        },\n        {\n            title: \"Curated Collections\",\n            description: \"Our selection of gift items spans a wide spectrum of choices, from luxury indulgences to practical everyday essentials. We take pride in offering a meticulously curated collection, ensuring that you find the perfect gift for any occasion or recipient.\"\n        },\n        {\n            title: \"Impeccable Quality\",\n            description: \"Quality is our hallmark. We source our products from trusted suppliers and artisans, ensuring that each item in our inventory meets the highest standards of craftsmanship and durability.\"\n        },\n        {\n            title: \"Sustainable Gifting\",\n            description: \"We are committed to sustainability and environmentally responsible practices. Many of our products are sourced from eco-friendly materials, and we offer options for sustainable packaging, ensuring that your gifts align with your values.\"\n        }\n    ],\n    clients: [\n        \"Samsung\",\n        \"Google\",\n        \"Centuryply\",\n        \"Orient\",\n        \"Tata\",\n        \"Reliance\",\n        \"Infosys\",\n        \"Wipro\"\n    ],\n    social: {\n        facebook: \"https://www.facebook.com/impacktgiftingsolutions\",\n        instagram: \"https://www.instagram.com/impacktgiftingsolutions/\",\n        linkedin: \"https://www.linkedin.com/company/impackt-gifting-solutions\"\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/data/content.ts\n");

